// Generated from a 2-second, 10 fps, 32x32 H.264 color source. No user data.
const DUMMY_VIDEO_20_SAMPLES_BASE64 = "";

export function dummyVideo20SamplesBytes(): Uint8Array {
  const binary = atob(DUMMY_VIDEO_20_SAMPLES_BASE64);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}
